t = int(input())
for i in range(t):
	n = int(input())
	a = list(map(int, input().split()))
	b = list(map(int, input().split()))
	aind = []
	bind = []
	for i in range(n):
		aind.append([a[i], i])
	for i in range(n):
		bind.append([b[i], i])
	aind.sort()
	bind.sort()
	c = 0
	for i in range(n):
		if aind[i][1] > bind[i][1]:
			c -= aind[i][0] * (aind[i][1] - bind[i][1])
		else:
			c += aind[i][0] * (bind[i][1] - aind[i][1])
	print(c)
